package recap

import (
	"context"
	"os/exec"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/gitremote"
)

// AggregateToolProfiles sums category counts across a slice of checkpoints.
// Returns nil when no checkpoint carries a ToolProfile so renderers can treat
// absence as "no data" without branching on Total == 0.
func AggregateToolProfiles(cps []RecapCheckpoint) *ToolProfile {
	out := &ToolProfile{Categories: map[string]ToolCategoryMetrics{}}
	any := false
	for _, c := range cps {
		if c.ToolProfile == nil {
			continue
		}
		any = true
		out.Total += c.ToolProfile.Total
		for k, v := range c.ToolProfile.Categories {
			m := out.Categories[k]
			m.Count += v.Count
			m.DurationMs += v.DurationMs
			out.Categories[k] = m
		}
	}
	if !any {
		return nil
	}
	return out
}

// LabelCount pairs a label with its occurrence count — used for sorted
// distribution rendering in the Labels panel.
type LabelCount struct {
	Label string
	Count int
}

// AggregateLabels collapses checkpoint labels into a count-descending slice.
// Ties broken alphabetically by label for deterministic output.
func AggregateLabels(cps []RecapCheckpoint) []LabelCount {
	counts := map[string]int{}
	for _, c := range cps {
		for _, lbl := range c.Labels {
			counts[lbl]++
		}
	}
	out := make([]LabelCount, 0, len(counts))
	for k, v := range counts {
		out = append(out, LabelCount{Label: k, Count: v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Label < out[j].Label
	})
	return out
}

// WorktreeRollup is the per-worktree summary shown in the bottom panel.
type WorktreeRollup struct {
	WorktreeID      string
	WorktreePath    string
	Repo            string
	SessionCount    int
	LastActivity    time.Time
	HasUncommitted  bool // any session has checkpoints without a linked commit
	Agents          []string
}

// AggregateByWorktree groups sessions by WorktreeID (falling back to
// WorktreePath when ID is empty) and returns one rollup per distinct
// worktree, sorted by most recent LastActivity first.
func AggregateByWorktree(sessions []RecapSession) []WorktreeRollup {
	type bucket struct {
		rollup WorktreeRollup
		agents map[string]bool
	}
	m := map[string]*bucket{}
	for _, s := range sessions {
		key := s.WorktreeID
		if key == "" {
			key = s.WorktreePath
		}
		if key == "" {
			continue
		}
		b, ok := m[key]
		if !ok {
			b = &bucket{
				rollup: WorktreeRollup{
					WorktreeID:   s.WorktreeID,
					WorktreePath: s.WorktreePath,
					Repo:         s.Repo,
				},
				agents: map[string]bool{},
			}
			m[key] = b
		}
		b.rollup.SessionCount++
		if s.LastInteraction.After(b.rollup.LastActivity) {
			b.rollup.LastActivity = s.LastInteraction
		}
		for _, a := range s.AgentsUsed {
			b.agents[a] = true
		}
		for _, cp := range s.Checkpoints {
			if cp.LinkedCommit == "" {
				b.rollup.HasUncommitted = true
				break
			}
		}
	}
	out := make([]WorktreeRollup, 0, len(m))
	for _, b := range m {
		for a := range b.agents {
			b.rollup.Agents = append(b.rollup.Agents, a)
		}
		sort.Strings(b.rollup.Agents)
		out = append(out, b.rollup)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].LastActivity.Equal(out[j].LastActivity) {
			return out[i].LastActivity.After(out[j].LastActivity)
		}
		return out[i].WorktreeID < out[j].WorktreeID
	})
	return out
}

// ResolveRepoFromWorktree returns the "owner/repo" slug for the git repo at
// worktreePath, using `git -C <path> remote get-url origin`. Returns
// "unknown" when the remote is absent or unparseable — never errors, since
// an unknown repo is a valid display state.
func ResolveRepoFromWorktree(ctx context.Context, worktreePath string) string {
	if worktreePath == "" {
		return "unknown"
	}
	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "remote", "get-url", "origin") //nolint:gosec // path comes from session state written by the CLI
	raw, err := cmd.Output()
	if err != nil {
		return "unknown"
	}
