	if err != nil || info == nil || info.Owner == "" || info.Repo == "" {
		return "unknown"
	}
	return info.Owner + "/" + info.Repo
}

// FilterByRange returns sessions whose StartedAt or LastInteraction falls
// within [start, end) — half-open to avoid double-counting boundaries.
func FilterByRange(sessions []RecapSession, start, end time.Time) []RecapSession {
	out := make([]RecapSession, 0, len(sessions))
	for _, s := range sessions {
		if overlapsRange(s, start, end) {
			out = append(out, s)
		}
	}
	return out
}

func overlapsRange(s RecapSession, start, end time.Time) bool {
	// A session is in-range if any activity timestamp we track lands in [start, end).
	candidates := []time.Time{s.StartedAt, s.LastInteraction}
	for _, t := range candidates {
		if t.IsZero() {
			continue
		}
		if (t.Equal(start) || t.After(start)) && t.Before(end) {
			return true
		}
	}
	return false
}

// Range helpers. All return [start, end) half-open in the caller's location.
// "now" is passed explicitly so callers can fix time for tests.

func RangeToday(now time.Time) (time.Time, time.Time) {
	start := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
	return start, start.AddDate(0, 0, 1)
}

func RangeLastWeek(now time.Time) (time.Time, time.Time) {
	_, end := RangeToday(now)
	return end.AddDate(0, 0, -7), end
}

func RangeLastMonth(now time.Time) (time.Time, time.Time) {
	// Current calendar month, not rolling 30 days.
	start := time.Date(now.Year(), now.Month(), 1, 0, 0, 0, 0, now.Location())
	end := start.AddDate(0, 1, 0)
	return start, end
}

func RangeLast30d(now time.Time) (time.Time, time.Time) {
	_, end := RangeToday(now)
	return end.AddDate(0, 0, -30), end
}

func RangeLast90d(now time.Time) (time.Time, time.Time) {
	_, end := RangeToday(now)
	return end.AddDate(0, 0, -90), end
}

