package recap

import (
	"sort"
	"time"
)

// TopAgent returns the agent that owns the most sessions in the slice, along
// with its session count. When sessions is empty, returns ("", 0).
// Ties broken alphabetically for determinism.
func TopAgent(sessions []RecapSession) (string, int) {
	counts := map[string]int{}
	for _, s := range sessions {
		for _, a := range s.AgentsUsed {
			counts[a]++
		}
	}
	return topKV(counts)
}

// TopModel returns the model appearing in the most sessions. Same semantics
// as TopAgent for ties and empty input.
func TopModel(sessions []RecapSession) (string, int) {
	counts := map[string]int{}
	for _, s := range sessions {
		for _, m := range s.ModelsUsed {
			counts[m]++
		}
	}
	return topKV(counts)
}

// TopSkill returns the skill with the most references across checkpoints.
// Skill data comes from server enrichment (CheckpointAnalysis.skillsUsed),
// so this returns ("", 0) when no checkpoint has been enriched yet.
func TopSkill(cps []RecapCheckpoint) (string, int) {
	counts := map[string]int{}
	for _, c := range cps {
		for _, s := range c.Labels {
			// NOTE: RecapCheckpoint doesn't carry skillsUsed yet — it's on the
			// server-side CheckpointAnalysisResponse. When enrich.go is expanded
			// to attach skillsUsed to RecapCheckpoint, swap this loop's source
			// and add a SkillsUsed field to RecapCheckpoint.
			_ = s
		}
	}
	// Today, return ("", 0) — caller treats as no data.
	return topKV(counts)
}

// EmergingSkills returns skills that appear in `this` period but not in
// `prior`, ordered by descending this-period count. Designed for the
// "new this week" insight line. Empty input returns nil.
func EmergingSkills(this, prior []RecapCheckpoint) []string {
	priorSet := map[string]bool{}
	for _, c := range prior {
		for _, lbl := range c.Labels {
			priorSet[lbl] = true
		}
	}
	thisCounts := map[string]int{}
	for _, c := range this {
		for _, lbl := range c.Labels {
			if !priorSet[lbl] {
				thisCounts[lbl]++
			}
		}
	}
	if len(thisCounts) == 0 {
		return nil
	}
	out := make([]string, 0, len(thisCounts))
	for k := range thisCounts {
		out = append(out, k)
	}
	sort.Slice(out, func(i, j int) bool {
		if thisCounts[out[i]] != thisCounts[out[j]] {
			return thisCounts[out[i]] > thisCounts[out[j]]
		}
		return out[i] < out[j]
	})
	return out
}

// LongestStreak returns the longest run of consecutive calendar days (in
// sessions' timezone) with any session activity, and the streak's start date.
// When labelFilter is non-empty, only sessions whose checkpoints carry that
// label contribute. Returns (0, zero time) when no qualifying days exist.
func LongestStreak(sessions []RecapSession, labelFilter string) (int, time.Time) {
	days := map[string]time.Time{}
	for _, s := range sessions {
		if labelFilter != "" && !sessionHasLabel(s, labelFilter) {
			continue
		}
		if s.StartedAt.IsZero() {
			continue
		}
		d := dayKey(s.StartedAt)
		if _, ok := days[d]; !ok {
			days[d] = time.Date(s.StartedAt.Year(), s.StartedAt.Month(), s.StartedAt.Day(), 0, 0, 0, 0, s.StartedAt.Location())
		}
	}
	if len(days) == 0 {
		return 0, time.Time{}
	}
	ordered := make([]time.Time, 0, len(days))
	for _, t := range days {
		ordered = append(ordered, t)
	}
	sort.Slice(ordered, func(i, j int) bool { return ordered[i].Before(ordered[j]) })

	bestLen := 1
	bestStart := ordered[0]
	curLen := 1
	curStart := ordered[0]
	for i := 1; i < len(ordered); i++ {
		if ordered[i].Sub(ordered[i-1]) == 24*time.Hour {
			curLen++
		} else {
			if curLen > bestLen {
				bestLen = curLen
				bestStart = curStart
			}
			curLen = 1
			curStart = ordered[i]
		}
	}
	if curLen > bestLen {
		bestLen = curLen
		bestStart = curStart
	}
	return bestLen, bestStart
}

// MostActiveDay returns the day-of-week with the highest checkpoint count
// across all sessions in the slice. Returns (Sunday, 0) when input is empty
// so callers can treat zero-count as "no data."
func MostActiveDay(sessions []RecapSession) (time.Weekday, int) {
	counts := [7]int{}
	for _, s := range sessions {
		for _, cp := range s.Checkpoints {
			counts[cp.CreatedAt.Weekday()]++
		}
	}
	bestIdx := 0
	for i := 1; i < 7; i++ {
		if counts[i] > counts[bestIdx] {
			bestIdx = i
		}
	}
	return time.Weekday(bestIdx), counts[bestIdx]
}

// Delta describes a period-over-period change in an integer metric.
// Used for WoW arrows in the Week tab header. Sign of Change matches
// Direction for easy rendering.
type Delta struct {
	Current   int
	Prior     int
	Change    float64 // (Current - Prior) / Prior; 0 when Prior == 0
	Direction int     // -1, 0, +1
}

// WeekOverWeekDelta compares two integer week totals and returns a Delta.
// Prior == 0 with Current > 0 yields Direction +1 but Change 0 (infinity
// isn't renderable); callers show "new this week" instead of a percentage.
func WeekOverWeekDelta(current, prior int) Delta {
	d := Delta{Current: current, Prior: prior}
	if prior > 0 {
		d.Change = float64(current-prior) / float64(prior)
	}
	switch {
	case current > prior:
		d.Direction = 1
	case current < prior:
		d.Direction = -1
	}
	return d
}

// ActionHint names a primary next action to surface on a session row.
// One hint per session — determined by NextAction's priority ordering.
type ActionHint string

const (
	ActionNone    ActionHint = ""
	ActionResume  ActionHint = "resume"
	ActionCommit  ActionHint = "commit"
	ActionPush    ActionHint = "push"
	ActionClean   ActionHint = "clean"
)

// NextAction picks a single primary action for the session. First match
// wins, so order reflects priority:
//
//  1. Commit  — has checkpoints that aren't linked to any commit yet
//  2. Push    — checkpoints linked locally but not yet on remote
//               (caller populates via a future "pushed" marker — today
//               this path is dormant; we still encode the priority
//               so rendering can wire it later without re-ordering)
//  3. Clean   — ended >7 days ago with no follow-up activity
//  4. Resume  — idle/active session with no pending commits
//  5. None    — otherwise
func NextAction(s RecapSession) ActionHint {
	if hasUncommittedCheckpoints(s) {
		return ActionCommit
	}
	if s.EndedAt != nil && time.Since(*s.EndedAt) > 7*24*time.Hour {
		return ActionClean
	}
	if s.IsActive || s.Phase == "IDLE" {
		return ActionResume
	}
	return ActionNone
}

// IdleWithUncommitted returns sessions where work has paused but checkpoints
// haven't been linked to commits — the "come back and commit this" list.
func IdleWithUncommitted(sessions []RecapSession) []RecapSession {
	var out []RecapSession
	for _, s := range sessions {
		if !hasUncommittedCheckpoints(s) {
			continue
		}
		if s.IsActive || s.Phase == "IDLE" || s.EndedAt != nil {
			out = append(out, s)
		}
	}
	return out
}

// helpers (package-private) ---------------------------------------------------

func topKV(counts map[string]int) (string, int) {
	if len(counts) == 0 {
		return "", 0
	}
	type kv struct {
		k string
		v int
	}
	all := make([]kv, 0, len(counts))
	for k, v := range counts {
		all = append(all, kv{k, v})
	}
	sort.Slice(all, func(i, j int) bool {
		if all[i].v != all[j].v {
			return all[i].v > all[j].v
		}
		return all[i].k < all[j].k
	})
	return all[0].k, all[0].v
}

func sessionHasLabel(s RecapSession, label string) bool {
	for _, cp := range s.Checkpoints {
		for _, lbl := range cp.Labels {
			if lbl == label {
				return true
			}
		}
	}
	return false
}

func dayKey(t time.Time) string {
	return t.Format("2006-01-02")
}

func hasUncommittedCheckpoints(s RecapSession) bool {
	for _, cp := range s.Checkpoints {
		if cp.LinkedCommit == "" {
			return true
		}
	}
	return false
}

