		IsActive:    false,
		Checkpoints: []RecapCheckpoint{{LinkedCommit: "abc"}},
	}
	if got := NextAction(s); got != ActionNone {
		t.Errorf("NextAction = %q, want %q (none)", got, ActionNone)
	}
}

