	s := RecapSession{
		EndedAt:     &past,
		Checkpoints: []RecapCheckpoint{{LinkedCommit: ""}},
	}
	if got := NextAction(s); got != ActionCommit {
		t.Errorf("NextAction = %q, want %q (commit beats clean)", got, ActionCommit)
	}
}

