1	package recap
2	
3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// RenderStatic produces the full static (non-TUI) recap output for a view.
9	// Width is the outer terminal width — the function clamps to a 60-cell
10	// minimum and uses the space for panel borders + content padding.
11	//
12	// Accessible / piped mode: pass styles from newRecapStyles(false). Output
13	// then contains no ANSI escapes and no Unicode borders; panels degrade to
14	// section headers separated by blank lines.
15	func RenderStatic(view RecapView, styles recapStyles, width int) string {
16		if width < 60 {
17			width = 60
18		}
19		var b strings.Builder
20	
21		// Panel 1: Summary band.
22		b.WriteString(renderPanel(view.Title, renderSummaryBand(view.Summary, styles), width, styles))
23		b.WriteString("\n\n")
24	
25		// Panel 2: Activity strip — range-dependent.
26		b.WriteString(renderActivityStrip(view, styles))
27		b.WriteString("\n\n")
28	
29		// Panel 3: Session list.
30		b.WriteString(renderPanel("Sessions", renderSessionList(view.Sessions, styles), width, styles))
31		b.WriteString("\n\n")
32	
33		// Panel 4: Repos · Worktrees · Labels (3-column bottom panel).
34		b.WriteString(renderBottomPanel(view, styles))
35	
36		return b.String()
37	}
38	
39	func renderSummaryBand(s SummaryBand, styles recapStyles) string {
40		kv := func(label, value string) string {
41			return styles.label.Render(label) + "  " + styles.value.Render(value)
42		}
43	
44		dom := "—"
45		if s.DominantLabel != "" {
46			dom = fmt.Sprintf("▪ %s  %d%%", s.DominantLabel, int(s.DominantLabelPct*100))
47		}
48	
49		topAgent := s.TopAgent
50		if topAgent == "" {
51			topAgent = "—"
52		}
53		if s.AgentFilter != "" {
54			topAgent = styles.accent.Render("["+s.AgentFilter+"]") + " (filter)"
55		}
56		topSkill := "—" // skill wiring lives in a later chunk; keep the slot visible
57		topModel := s.TopModel
58		if topModel == "" {
59			topModel = "—"
60		}
61	
62		line1 := kv("Top agent", topAgent) + "  " + kv("Top skill", topSkill)
63		line2 := kv("Dominant ", dom) + "  " + kv("Top model", topModel)
64		totals := fmt.Sprintf("%d sessions · %d checkpoints · %s tokens · %d commits",
65			s.SessionCount, s.CheckpointCount, formatTokens(s.TokenTotal), s.CommitCount)
66		line3 := kv("Totals    ", totals)
67		return line1 + "\n" + line2 + "\n\n" + line3
68	}
69	
70	func renderActivityStrip(view RecapView, styles recapStyles) string {
71		if len(view.Activity) == 0 {
72			return styles.muted.Render("  (no activity in range)")
73		}
74		var header string
75		switch view.Range {
76		case RangeDay:
77			header = "Activity (24h)"
78		case RangeWeek:
79			header = "Activity (7d)"
80		case RangeMonth:
81			header = "Activity (this month)"
82		case Range30d:
83			header = "Activity (30d)"
84		case Range90d:
85			header = "Activity (90d)"
86		default:
87			header = "Activity"
88		}
89	
90		if view.Range == RangeDay && len(view.Activity) == 24 {
91			var events [24]int
92			copy(events[:], view.Activity)
93			return styles.label.Render(header) + "\n" + renderIntraDayStrip(events, styles)
94		}
95		return styles.label.Render(header) + "\n" + renderHeatmapStrip(view.Activity, maxOf(view.Activity), styles)
96	}
97	
98	func renderSessionList(rows []SessionRow, styles recapStyles) string {
99		if len(rows) == 0 {
100			return styles.muted.Render("(no sessions in range)")
101		}
102		var b strings.Builder
103		for i, r := range rows {
104			agent := r.Agent
105			if agent == "" {
106				agent = "unknown"
107			}
108			label := r.Label
109			if label == "" {
110				label = styles.muted.Render("—")
111			}
112			hint := string(r.Hint)
113			hintStyle := styles.styleForHint(r.Hint)
114			hintRendered := ""
115			if hint != "" {
116				hintRendered = hintStyle.Render("▶ " + hint)
117			}
118			line := fmt.Sprintf("%s %-14s %-8s ▪ %-16s %2d cp   %s",
119				styles.accent.Render(r.Badge),
120				agent,
121				r.Span,
122				label,
123				r.Checkpoints,
124				hintRendered,
125			)
126			b.WriteString(strings.TrimRight(line, " "))
127			if i < len(rows)-1 {
128				b.WriteString("\n")
129			}
130		}
131		return b.String()
132	}
133	
134	func renderBottomPanel(view RecapView, styles recapStyles) string {
135		// 3 columns: Repos (optional), Worktrees, Labels.
136		// Simple left-aligned columns; width split handled by caller's terminal.
137		var cols []string
138	
139		if len(view.Repos) > 0 {
140			var rb strings.Builder
141			rb.WriteString(styles.label.Render("Repos") + "\n")
142			for _, r := range view.Repos {
143				fmt.Fprintf(&rb, "%-20s %d sess\n", r.Repo, r.SessionCount)
144			}
145			cols = append(cols, strings.TrimRight(rb.String(), "\n"))
146		}
147	
148		if len(view.Worktrees) > 0 {
149			var wb strings.Builder
150			wb.WriteString(styles.label.Render("Worktrees") + "\n")
151			for _, w := range view.Worktrees {
152				marker := " "
153				if w.HasUncommitted {
154					marker = styles.warn.Render("⇈")
155				}
156				id := w.WorktreeID
157				if id == "" {
158					id = "(default)"
159				}
160				fmt.Fprintf(&wb, "%-20s %d sess %s\n", id, w.SessionCount, marker)
161			}
162			cols = append(cols, strings.TrimRight(wb.String(), "\n"))
163		}
164	
165		if len(view.Labels) > 0 {
166			var lb strings.Builder
167			lb.WriteString(styles.label.Render("Labels") + "\n")
168			// Use max count as scale for gradient bar so the topmost label is full.
169			maxCount := 0
170			for _, l := range view.Labels {
171				if l.Count > maxCount {
172					maxCount = l.Count
173				}
174			}
175			for _, l := range view.Labels {
176				bar := renderGradientBar(l.Count, maxCount, 8, styles)
177				fmt.Fprintf(&lb, "%-16s %s\n", l.Label, bar)
178			}
179			cols = append(cols, strings.TrimRight(lb.String(), "\n"))
180		}
181	
182		if len(cols) == 0 {
183			return ""
184		}
185		return strings.Join(cols, "\n\n")
186	}
187	
188	// helpers -------------------------------------------------------------------
189	
190	func maxOf(xs []int) int {
191		m := 0
192		for _, v := range xs {
193			if v > m {
194				m = v
195			}
196		}
197		return m
198	}
199	
200	// formatTokens renders a token count compactly: 142000 → "142k", 1500000 → "1.5M".
201	func formatTokens(n int) string {
202		switch {
203		case n >= 1_000_000:
204			return fmt.Sprintf("%.1fM", float64(n)/1_000_000)
205		case n >= 1_000:
206			return fmt.Sprintf("%dk", n/1_000)
207		default:
208			return strconv.Itoa(n)
209		}
210	}

