9	// RangeKey names a pre-baked time range selectable via CLI flag or keyboard
10	// toggle. Day is the default; Month is calendar-aligned, 30d and 90d are
11	// rolling windows.
12	type RangeKey string
13	
14	const (
15		RangeDay     RangeKey = "day"
16		RangeWeek    RangeKey = "week"
17		RangeMonth   RangeKey = "month"
18		Range30d     RangeKey = "30d"
19		Range90d     RangeKey = "90d"
20		rangeDefault          = RangeDay
21	)
22	
23	// Title returns the human-readable label shown in the summary panel header.
24	func (r RangeKey) Title() string {
25		switch r {
26		case RangeDay:
27			return "Today"
28		case RangeWeek:
29			return "Last 7 days"
30		case RangeMonth:
31			return "This month"
32		case Range30d:
33			return "Last 30 days"
34		case Range90d:
35			return "Last 90 days"
36		}
37		return string(r)
38	}
39	
40	// bounds returns the half-open [start, end) interval for a RangeKey relative
41	// to a reference time (usually time.Now()). Local-time midnight boundaries
42	// so "today" starts where the user's clock starts.
43	func (r RangeKey) bounds(now time.Time) (time.Time, time.Time) {
44		dayStart := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
45		dayEnd := dayStart.AddDate(0, 0, 1)
46		switch r {
47		case RangeDay:
48			return dayStart, dayEnd
49		case RangeWeek:
50			return dayEnd.AddDate(0, 0, -7), dayEnd
51		case RangeMonth:
52			monthStart := time.Date(now.Year(), now.Month(), 1, 0, 0, 0, 0, now.Location())
53			return monthStart, monthStart.AddDate(0, 1, 0)
54		case Range30d:
55			return dayEnd.AddDate(0, 0, -30), dayEnd
56		case Range90d:
57			return dayEnd.AddDate(0, 0, -90), dayEnd
58		}
59		return dayStart, dayEnd
60	}
61	
62	// BuildOpts controls how the view is assembled.
63	type BuildOpts struct {
64		Range       RangeKey
65		AgentFilter string    // empty = all agents
66		Now         time.Time // injectable for deterministic tests
67	}
68	
69	// RecapView is everything a renderer needs. Pure data — no styling, no I/O.
70	// The Footer string is left to the renderer; the view exposes the raw bits.
71	type RecapView struct {
72		Title     string
73		Range     RangeKey
74		Summary   SummaryBand
75		Activity  []int // heatmap buckets; length depends on Range
76		Sessions  []SessionRow
77		Repos     []RepoLine // nil when all sessions share one repo
78		Worktrees []WorktreeRollup
79		Labels    []LabelLine
80	}
81	
82	// SummaryBand holds the headline facts at the top of every view.
83	type SummaryBand struct {
84		TopAgent         string
85		TopAgentCount    int
86		TopModel         string
87		TopModelCount    int
88		DominantLabel    string
89		DominantLabelPct float64 // 0-1
