91		CheckpointCount  int
92		TokenTotal       int
93		CommitCount      int
94		AgentFilter      string // non-empty when filtered — rendered as chip
95	}
96	
97	// SessionRow is a row in the middle panel's chronological list.
98	type SessionRow struct {
99		Badge       string // ● live, ◌ idle
