122	// BuildRecapView projects a slice of sessions into a RecapView for the
123	// given range + agent filter. Pure — no I/O, no git — so it's easy to
124	// fixture-test and safe to call from TUI update loops.
125	func BuildRecapView(sessions []RecapSession, opts BuildOpts) RecapView {
126		if opts.Range == "" {
127			opts.Range = rangeDefault
128		}
129		if opts.Now.IsZero() {
130			opts.Now = time.Now()
131		}
132		start, end := opts.Range.bounds(opts.Now)
133	
134		// Filter by range first, then by agent. Order matters for performance
135		// but not for correctness — both filters are commutative.
136		filtered := make([]RecapSession, 0, len(sessions))
137		for _, s := range sessions {
138			if !inRange(s, start, end) {
