	t.Parallel()
	cmd := newRecapCmd()
	for _, name := range []string{"day", "week", "month", "30", "90", "agent", "format"} {
		if f := cmd.Flag(name); f == nil {
			t.Errorf("flag --%s not registered", name)
		}
	}
}

