// helpers --------------------------------------------------------------------

func labelCountsSorted(m map[string]int) []LabelCount {
	out := make([]LabelCount, 0, len(m))
	for k, v := range m {
		out = append(out, LabelCount{Label: k, Count: v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Label < out[j].Label
	})
	return out
}

// LabelCount is defined in aggregate.go; documented here for readability.
type _ = LabelCount //nolint:unused // reference for readers

func topNByCount(m map[string]int, n int) []string {
	type kv struct {
		k string
		v int
	}
	all := make([]kv, 0, len(m))
	for k, v := range m {
		all = append(all, kv{k, v})
	}
	sort.Slice(all, func(i, j int) bool {
		if all[i].v != all[j].v {
			return all[i].v > all[j].v
		}
		return all[i].k < all[j].k
	})
	if len(all) > n {
		all = all[:n]
	}
	out := make([]string, 0, len(all))
	for _, e := range all {
		out = append(out, e.k)
	}
	return out
}

func reposSorted(m map[string]int) []RepoLine {
	out := make([]RepoLine, 0, len(m))
	for k, v := range m {
		out = append(out, RepoLine{Repo: k, SessionCount: v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].SessionCount != out[j].SessionCount {
			return out[i].SessionCount > out[j].SessionCount
		}
		return out[i].Repo < out[j].Repo
	})
	if len(out) > 3 {
		out = out[:3]
	}
	return out
}

func topLabelsInline(labels []LabelCount, styles Styles) string {
	if len(labels) == 0 {
		return styles.muted.Render("—")
	}
	n := len(labels)
	if n > 3 {
		n = 3
	}
	total := 0
	for _, l := range labels {
		total += l.Count
	}
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		pct := 0
		if total > 0 {
			pct = (labels[i].Count * 100) / total
		}
		parts = append(parts, fmt.Sprintf("%s %d%%", styles.accent.Render(labels[i].Label), pct))
	}
	return strings.Join(parts, "  ")
}

func tokensIfAny(n int, show bool) string {
	if !show {
		return ""
	}
	if n == 0 {
		return "—"
	}
	return formatTokens(n)
}

// padValue renders a styled value padded to width, stripped of ANSI for
// length calculation when needed. Uses a plain left-pad since our values are
// ASCII-safe (digits + token suffixes).
func padValue(s string, width int, style interface{ Render(string) string }) string {
	// We approximate width on the unstyled string since lipgloss styles don't
	// widen the visible text. This works because all values here are ASCII.
	if len(s) < width {
		s += strings.Repeat(" ", width-len(s))
	}
	return style.Render(s)
