1	package recap
2	
3	import (
4		"time"
5	
6		tea "github.com/charmbracelet/bubbletea"
7	)
8	
9	// TUIModel backs the interactive recap view. It keeps the raw sessions so
10	// range + agent toggles can rebuild the View instantly without re-fetching.
11	type TUIModel struct {
12		sessions    []RecapSession
13		view        View
14		agentFilter string
15		agents      []string // agents present in sessions, for cycling
16		mode        ViewMode // me / contributors / both
17		styles      Styles
18		width       int
19		height      int
20	}
21	
22	// NewTUIModel wraps a pre-built View with the state bubbletea needs for
23	// interactive toggles. agentFilter is the initial filter ("" = all agents).
24	func NewTUIModel(sessions []RecapSession, initial View, agentFilter string) TUIModel {
25		mode := initial.Mode
26		if mode == "" {
27			mode = ViewBoth
28		}
29		return TUIModel{
30			sessions:    sessions,
31			view:        initial,
32			agentFilter: agentFilter,
33			agents:      distinctAgents(sessions),
34			mode:        mode,
35			styles:      NewStyles(true),
36			width:       100,
37			height:      24,
38		}
39	}
40	
41	// Init is a no-op — no async work on startup.
42	func (m TUIModel) Init() tea.Cmd { return nil }
43	
44	// Update dispatches on keyboard and window-resize messages. Range + agent
45	// toggles rebuild the View via BuildView; nothing else changes.
46	//
47	
48	func (m TUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
49		switch msg := msg.(type) {
50		case tea.WindowSizeMsg:
51			m.width, m.height = msg.Width, msg.Height
52			return m, nil
53		case tea.KeyMsg:
54			return m.handleKey(msg)
55		}
56		return m, nil
57	}
58	
59	func (m TUIModel) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
60		key := msg.String()
61		switch key {
62		case "q", "ctrl+c", "esc":
63			return m, tea.Quit
64		case "1", "d":
65			m.view = rebuildView(m.sessions, RangeDay, m.agentFilter, m.mode)
66		case "2", "w":
67			m.view = rebuildView(m.sessions, RangeWeek, m.agentFilter, m.mode)
68		case "3", "m":
69			m.view = rebuildView(m.sessions, RangeMonth, m.agentFilter, m.mode)
70		case "4":
71			m.view = rebuildView(m.sessions, Range30d, m.agentFilter, m.mode)
72		case "5":
73			m.view = rebuildView(m.sessions, Range90d, m.agentFilter, m.mode)
74		case "a":
75			m.agentFilter = cycleAgent(m.agents, m.agentFilter)
76			m.view = rebuildView(m.sessions, m.view.Range, m.agentFilter, m.mode)
77		case "v":
78			m.mode = cycleMode(m.mode)
79			m.view = rebuildView(m.sessions, m.view.Range, m.agentFilter, m.mode)
80		}
81		return m, nil
82	}
83	
84	// View renders the current state via the static renderer, plus a help line
85	// at the bottom so users discover the keybinds without reading docs.
86	func (m TUIModel) View() string {
87		body := RenderStatic(m.view, m.styles, m.width)
88		help := m.styles.help.Render("  d w m 4 5  range  ·  a  agent filter  ·  v  view (me/contributors/both)  ·  q  quit")
89		return body + "\n" + help
90	}
91	
92	// rebuildView is a tiny wrapper that anchors Now at call time so range math
93	// stays correct across long-running TUI sessions.
94	func rebuildView(sessions []RecapSession, r RangeKey, agent string, mode ViewMode) View {
95		return BuildView(sessions, BuildOpts{Range: r, AgentFilter: agent, Mode: mode, Now: time.Now()})
96	}
97	
98	// cycleMode advances the view mode: both → me → contributors → both.
99	func cycleMode(current ViewMode) ViewMode {
100		switch current {
101		case ViewBoth:
102			return ViewMe
103		case ViewMe:
104			return ViewContributors
105		case ViewContributors:
106			return ViewBoth
107		}
108		return ViewBoth
109	}
110	
111	// cycleAgent advances the filter in a stable round-robin: "" → agents[0] →
112	// agents[1] → … → "". Stable order means the same key press always moves
113	// to the same next agent.
114	func cycleAgent(agents []string, current string) string {
115		if len(agents) == 0 {
116			return ""
117		}
118		if current == "" {
119			return agents[0]
120		}
121		for i, a := range agents {
122			if a == current {
123				if i+1 < len(agents) {
124					return agents[i+1]
125				}
126				return ""
127			}
128		}
129		return ""
130	}
131	
132	func distinctAgents(sessions []RecapSession) []string {
133		seen := map[string]bool{}
134		var out []string
135		for _, s := range sessions {
136			for _, a := range s.AgentsUsed {
137				if !seen[a] {
138					seen[a] = true
139					out = append(out, a)
140				}
141			}
142		}
143		return out
144	}

